  ('1752444d-ddd0-5b9b-9e1e-949d563af032', 'vnt-09', 'riviera-rimless-titanium', 'Riviera Rimless Minimalist', 'Riviera Rimless', 'Sunglasses', 'Unisex', 3850, 4600, 'BDT', '৳', 'Minimalist aesthetic design featuring beveled-edge lenses mounted directly to silver-tone metal temples for an unobstructed field of vision.', 'Weightless-look rimless sunglasses with beveled edge lenses.', 'Aviator', 'Dark Metal-Look Alloy', 'Polished Silver Tone', 'Smokey Rose Gradient', 'Gradient Tint', 'Architectural', 'Universal', ARRAY['Clean rimless perimeter aesthetic', 'Beveled-edge lens detailing', 'Polished silver-tone metal temples', 'Unobstructed peripheral viewing']::text[], 'Limited Edition', true, false, false, true, true, 8, 'Riviera Rimless Sunglasses | VANTAIRE EYEWEAR', 'Minimalist rimless sunglasses with beveled edges and silver-tone temples. Order via WhatsApp.'),
  ('cbe19ea0-a9ef-5657-afe5-2187d4066b2f', 'vnt-10', 'sienna-vintage-gradient-round', 'Sienna Vintage Gradient Round', 'Sienna Round', 'Sunglasses', 'Women', 2950, NULL, 'BDT', '৳', 'A soft, 1970s European cinematic expression. Warm amber honey-look frames enclosing sunset sienna gradient lenses for unforgettable golden-hour radiance.', 'Cinematic honey-look frame with warm sienna sunset gradient lenses.', 'Round', 'Tortoise Acetate-Look', 'Warm Honey Amber', 'Sienna Sunset Gradient', 'Gradient Tint', 'Retro', 'Medium', ARRAY['Warm translucent honey amber tone', 'Soft sunset sienna gradient tint', 'Keyhole-style bridge detailing', 'Comfort-rounded frame edges']::text[], 'Signature Edit', false, false, false, true, true, 9, 'Sienna Vintage Gradient Round Sunglasses | VANTAIRE EYEWEAR', 'Honey amber round sunglasses with sunset gradient lenses. Fast delivery nationwide across Bangladesh.'),
